"use client";

import Link from "next/link";
import { useParams } from "next/navigation";
import { useEffect, useState } from "react";
import { ArrowLeft, ArrowRight, Bookmark, CalendarClock, Check, CheckCircle2, ChevronRight, Clock3, Copy, Download, ExternalLink, FileText, HeartHandshake, Share2, Sparkles, Target, X } from "lucide-react";
import { api, getToken } from "@/lib/api";
import { Opportunity, OpportunityApplication, Page } from "@/lib/types";
import { opportunityIdFromRoute, opportunityPath } from "@/lib/routes";
import { OpportunityCommunityActions } from "@/components/opportunity-community-actions";
import { downloadOpportunityShareCard } from "@/lib/opportunity-share-card";

const labels: Record<string, string> = { scholarship: "Scholarship", grant: "Grant", job: "Job", internship: "Internship", fellowship: "Fellowship", competition: "Competition", training: "Training", startup: "Startup / Co-founder", funding: "Business funding", tender: "Tenders & Procurement" };
const formatDate = (value: string | null) => value ? new Intl.DateTimeFormat("en", { month: "long", day: "numeric", year: "numeric" }).format(new Date(value)) : "No deadline listed";
const daysLeft = (value: string | null) => value ? Math.max(0, Math.ceil((new Date(value).getTime() - Date.now()) / 86400000)) : null;
const place = (item: Opportunity) => item.is_remote ? "Remote" : item.location_label || item.country || "Open location";

function Fact({ label, value }: { label: string; value: string }) { return <div className="opportunity-fact"><small>{label}</small><strong>{value}</strong></div>; }

export default function OpportunityDetailPage() {
  const { id } = useParams<{ id: string }>();
  const [item, setItem] = useState<Opportunity | null>(null); const [similar, setSimilar] = useState<Opportunity[]>([]); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [tracking, setTracking] = useState(false); const [applyOpen, setApplyOpen] = useState(false); const [shareOpen, setShareOpen] = useState(false); const [copied, setCopied] = useState(false); const [downloading, setDownloading] = useState(false); const [applicationMessage, setApplicationMessage] = useState(""); const [additionalInformation, setAdditionalInformation] = useState(""); const [sharedFields, setSharedFields] = useState<string[]>(["profile", "skills"]); const [error, setError] = useState(""); const [authenticated, setAuthenticated] = useState(false);
  useEffect(() => { setAuthenticated(Boolean(getToken())); }, []);
  const opportunityId = opportunityIdFromRoute(id);
  useEffect(() => { const personalized = Boolean(getToken()); const relatedEndpoint = personalized ? "/opportunities/matches/" : "/opportunities/"; Promise.all([api<Opportunity>(`/opportunities/${opportunityId}/`), api<Page<Opportunity>>(relatedEndpoint)]).then(([opportunity, page]) => { setItem(opportunity); setSimilar(page.results.filter((candidate) => candidate.public_id !== opportunity.public_id && (personalized || candidate.category === opportunity.category)).slice(0, 3)); }).catch(() => setError("This opportunity could not be loaded.")).finally(() => setLoading(false)); }, [opportunityId]);
  if (loading) return <main className="opportunity-detail container"><p>Loading opportunity...</p></main>;
  if (!item) return <main className="opportunity-detail container"><p className="opportunity-error">{error || "Opportunity not found."}</p><Link href="/opportunities" className="text-link">Back to opportunities</Link></main>;
  const opportunity = item; const match = opportunity.match; const opportunityPublicId = opportunity.public_id; const remaining = daysLeft(opportunity.deadline); const saved = Boolean(opportunity.saved_status); const tracked = Boolean(opportunity.application_status); const score = match?.score ?? null; const readiness = authenticated && score !== null ? Math.min(94, Math.max(42, score - (tracked ? 0 : 18))) : null; const gaps = match?.missing || [];
  function toggleSave() { if (!getToken()) { window.location.href = loginHref; return; } setSaving(true); api(`/opportunities/${opportunityPublicId}/save/`, { method: saved ? "DELETE" : "POST", body: JSON.stringify({}) }).then(() => setItem((current) => current ? { ...current, saved_status: saved ? null : "saved" } : current)).finally(() => setSaving(false)); }
  function startTracking() { if (!getToken()) { window.location.href = loginHref; return; } setApplyOpen(true); }
  function startExternalTracking() { if (!getToken()) { window.location.href = loginHref; return; } setTracking(true); api<OpportunityApplication>("/opportunity-applications/", { method: "POST", body: JSON.stringify({ opportunity_id: opportunityPublicId, status: "preparing" }) }).then((application) => setItem((current) => current ? { ...current, application_status: application.status } : current)).catch((trackError) => setError((trackError as Error).message)).finally(() => setTracking(false)); }
  function submitApplication() { setTracking(true); api<OpportunityApplication>("/opportunity-applications/", { method: "POST", body: JSON.stringify({ opportunity_id: opportunityPublicId, status: "applied", application_message: applicationMessage, additional_information: additionalInformation, shared_fields: sharedFields }) }).then((application) => { setItem((current) => current ? { ...current, application_status: application.status, application_count: current.application_count + 1 } : current); setApplyOpen(false); }).catch((submitError) => setError((submitError as Error).message)).finally(() => setTracking(false)); }
  const attendance = item.is_remote ? "Remote" : item.requires_local_residency ? "Local residents only" : item.requires_physical_presence ? "In person · relocation possible" : "Check provider details";
  const facts = [{ label: "Type", value: labels[item.category] || item.category }, { label: "Location", value: place(item) }, { label: "Attendance", value: attendance }, { label: "Applied", value: String(item.application_count || 0) }, { label: "Views", value: String(item.view_count || 0) }, { label: "Application", value: item.application_mode === "internal" ? "Apply inside Getneba" : "External website" }, { label: "Eligibility", value: item.eligible_countries?.join(" · ") || item.country || "Review requirements" }, { label: "Value", value: item.benefit || "See provider details" }, { label: "Education", value: item.education_levels?.join(", ") || "Any level" }, { label: "Provider", value: item.provider }, { label: "Deadline", value: formatDate(item.deadline) }];
  const detailPath = opportunityPath(item.title, opportunityPublicId);
  const loginHref = `/login?next=${encodeURIComponent(detailPath)}`;
  const shareUrl = typeof window === "undefined" ? detailPath : `${window.location.origin}${detailPath}`;
  const shareText = `Found this opportunity on GetNeba: ${item.title} by ${item.provider}. ${item.deadline ? `Deadline: ${formatDate(item.deadline)}. ` : ""}See details: ${shareUrl}`;
  const shareOptions: Array<[string, string, string]> = [["profile", "Basic profile", "Name, location and introduction"], ["skills", "Skills and experience", "What you can do and have worked on"], ["education", "Education", "Your academic background"], ["business", "Business or project", "Projects you are building"], ["documents", "Document list", "Documents available on your profile"]];
  async function copyShareText() { try { await navigator.clipboard.writeText(shareText); } catch { const field = document.createElement("textarea"); field.value = shareText; field.style.position = "fixed"; field.style.opacity = "0"; document.body.appendChild(field); field.select(); document.execCommand("copy"); field.remove(); } setCopied(true); window.setTimeout(() => setCopied(false), 2200); }
  async function downloadShareImage() {
    setDownloading(true);
    setError("");
    try {
      await downloadOpportunityShareCard(opportunity, shareUrl);
    } catch (downloadError) {
      setError((downloadError as Error).message || "Could not create the share image.");
    } finally {
      setDownloading(false);
    }
  }

  return <main className="opportunity-detail opportunity-detail-intelligence container">
    <Link href="/opportunities" className="detail-back"><ArrowLeft size={15} /> Back to opportunities</Link>
    <header className="intelligence-hero"><div className="intelligence-hero-copy"><span className="opportunity-type">{labels[item.category] || item.category}</span><h1>{item.title}</h1><p>{item.provider} · {place(item)}</p>{item.deadline && <span className="intelligence-deadline"><CalendarClock size={14} /> Deadline: {formatDate(item.deadline)}</span>}</div><div className="intelligence-hero-actions">{item.application_mode === "internal" ? authenticated ? <button className="button button-dark" onClick={startTracking}>Apply internally <HeartHandshake size={16} /></button> : <Link className="button button-dark" href={loginHref}>Sign in to apply <ArrowRight size={16} /></Link> : <a className="button button-dark" href={item.application_url} target="_blank" rel="noreferrer">Apply on provider website <ExternalLink size={16} /></a>}<button className={`button button-outline${saved ? " saved" : ""}`} onClick={toggleSave} disabled={saving}><Bookmark size={16} fill={saved ? "currentColor" : "none"} />{saved ? "Saved" : "Save"}</button><button className="button button-outline share-trigger" onClick={() => setShareOpen((open) => !open)} aria-expanded={shareOpen} aria-controls="opportunity-share-panel"><Share2 size={16} />Share</button></div></header>
    {shareOpen && <section className="opportunity-share-panel" id="opportunity-share-panel" aria-label="Share this opportunity"><div className="opportunity-share-intro"><span className="share-panel-icon"><Share2 size={18} /></span><div><span className="eyebrow">PASS IT ON</span><h2>Share this opportunity</h2><p>Give someone a clear next step with a ready-made image or message.</p></div></div><div className="opportunity-share-actions"><button className="share-action-card" onClick={downloadShareImage} disabled={downloading}><span><Download size={18} /></span><strong>{downloading ? "Preparing image…" : "Download image"}</strong><small>Branded square PNG · 1:1</small></button><button className="share-action-card" onClick={copyShareText}><span>{copied ? <CheckCircle2 size={18} /> : <Copy size={18} />}</span><strong>{copied ? "Text copied" : "Copy WhatsApp text"}</strong><small>Short message with the opportunity link</small></button></div><div className="opportunity-share-preview"><span>MESSAGE PREVIEW</span><p>{shareText}</p></div></section>}
    <section className="fit-readout"><div className="fit-readout-score"><strong>{score === null ? "—" : `${score}%`}</strong><span>Match</span></div><div className="fit-readout-score readiness"><strong>{readiness === null ? "—" : `${readiness}%`}</strong><span>Ready</span></div><div className="fit-readout-copy"><span className="eyebrow">{authenticated ? "WHAT THIS MEANS FOR YOU" : "PERSONALIZED INSIGHT"}</span><h2>{!authenticated ? "Sign in to see how this opportunity fits your profile." : score !== null && score >= 75 ? "You appear to meet most of the published requirements." : "This could fit, but a few details need checking first."}</h2><p>{authenticated ? "Match is based on your Getneba profile and the published requirements — it is not a prediction of acceptance." : "Create a free account to unlock your match score, application tracking, and personalized next steps."}</p></div></section>
    <div className="opportunity-detail-layout"><div className="opportunity-detail-main">
      <section className="opportunity-detail-section fit-section"><div className="opportunity-detail-section-heading"><Target size={19} /><div><h2>Your opportunity fit</h2><p>Signals from your profile that fit this opportunity.</p></div></div><div className="fit-columns"><div><h3>Why you match</h3>{match?.reasons.length ? <div className="opportunity-check-list">{match.reasons.map((reason) => <span key={reason}><Check size={16} />{reason}</span>)}</div> : <p>{authenticated ? "Complete more of your profile to see a detailed match explanation." : "Sign in to compare the published requirements with your profile."}</p>}</div><div><h3>Potential gaps</h3>{!authenticated ? <p>We need your profile before we can identify possible gaps.</p> : gaps.length ? <div className="opportunity-gap-list">{gaps.map((gap) => <span key={gap}><Clock3 size={15} />{gap}</span>)}</div> : <p className="fit-positive"><Check size={15} /> No obvious gaps from your current profile.</p>}</div></div><Link href={authenticated ? "/profile" : loginHref} className="section-link">{authenticated ? "See how we calculated this" : "Sign in to check your fit"} <ChevronRight size={14} /></Link></section>
      <section className="opportunity-detail-section readiness-section"><div className="readiness-heading"><div><span className="eyebrow">YOUR PREPARATION PATH</span><h2>How ready are you?</h2><p>{readiness !== null && readiness >= 75 ? "You are close. A few focused steps can get you ready to apply." : "Sign in to see your personalized preparation path."}</p></div><strong>{readiness === null ? "—" : `${readiness}%`} <small>Ready</small></strong></div><div className="readiness-grid"><span className="ready"><Check size={14} /> Eligibility</span><span className="ready"><Check size={14} /> Getneba profile</span><span><Clock3 size={14} /> CV needs update</span><span><Clock3 size={14} /> Portfolio needs attention</span><span><Clock3 size={14} /> Application not started</span></div><Link href="/profile" className="button button-outline compact">Improve my readiness <ArrowRight size={14} /></Link></section>
      <section className="opportunity-detail-section"><div className="opportunity-detail-section-heading"><Sparkles size={19} /><div><h2>Quick facts</h2><p>The details most people want to know first.</p></div></div><div className="opportunity-facts">{facts.map((fact) => <Fact key={fact.label} {...fact} />)}</div></section>
      <section className="opportunity-detail-section"><div className="opportunity-detail-section-heading"><FileText size={19} /><div><h2>About this opportunity</h2></div></div><p className="opportunity-description">{item.summary}</p><h3>What you&apos;ll get</h3><div className="workspace-offering opportunity-offering-list"><span>{item.benefit || "A meaningful opportunity to grow"}</span><span>{place(item)}</span><span>Work with the {item.provider} team</span></div></section>
      <section className="opportunity-detail-section"><div className="opportunity-detail-section-heading"><Check size={19} /><div><h2>Eligibility</h2><p>Published requirements and your current signal.</p></div></div><p>{item.eligibility_notes || "Review the provider's official page for full eligibility details."}</p>{authenticated && match && <div className="opportunity-eligibility"><strong>Your eligibility</strong><span className={match.eligibility === "eligible" ? "eligible" : "needs-review"}>{match.eligibility === "eligible" ? "Published criteria match your profile" : match.eligibility === "unlikely" ? "A published requirement may not match" : "Review the published requirements"}</span></div>}</section>
      <section className="opportunity-detail-section"><div className="opportunity-detail-section-heading"><FileText size={19} /><div><h2>What you need to apply</h2><p>Confirm the exact list on the provider&apos;s application page.</p></div></div><div className="application-requirements"><div><strong>Required</strong><span><Check size={14} /> Profile information</span><span><Clock3 size={14} /> CV</span><span><Clock3 size={14} /> Portfolio</span></div><div><strong>Potentially required</strong><span><Clock3 size={14} /> Supporting documents</span><span><Clock3 size={14} /> Additional application questions</span></div></div><div className="opportunity-report-note"><X size={14} /> Requirements can change. Confirm the final list with the provider.</div></section>
      <section className="opportunity-detail-section application-plan"><div className="opportunity-detail-section-heading"><HeartHandshake size={19} /><div><h2>Your application plan</h2><p>A practical path from interest to action.</p></div></div><ol className="opportunity-steps"><li><b>01</b><span><strong>Update your CV</strong><small>Bring the experience most relevant to this opportunity forward.</small></span><Link href="/profile">Improve CV <ChevronRight size={13} /></Link></li><li><b>02</b><span><strong>Prepare your story</strong><small>Explain what you have built, learned, or want to contribute.</small></span><Link href="/assistant">Prepare with AI <ChevronRight size={13} /></Link></li><li><b>03</b><span><strong>Practice your interview</strong><small>Get ready for questions based on this opportunity.</small></span><Link href="/assistant">Start practice <ChevronRight size={13} /></Link></li><li><b>04</b><span><strong>{item.application_mode === "internal" ? "Apply inside Getneba" : "Apply on the provider website"}</strong><small>{item.application_mode === "internal" ? "Choose what to share and send your application directly to the provider." : "Submit through the official provider website."}</small></span>{item.application_mode === "external" ? <a href={item.application_url} target="_blank" rel="noreferrer">Apply now <ExternalLink size={13} /></a> : authenticated ? <button className="text-link" onClick={startTracking}>Apply now <ChevronRight size={13} /></button> : <Link className="text-link" href={loginHref}>Sign in to apply <ChevronRight size={13} /></Link>}</li></ol></section>
      <section className="opportunity-detail-section ask-section"><div className="opportunity-detail-section-heading"><Sparkles size={19} /><div><h2>Ask Getneba about this opportunity</h2><p>Get help with the opportunity, your fit, or what to do next.</p></div></div><div className="ask-prompt">What do you want to know?</div><div className="ask-chips"><Link href="/assistant">Why do I match?</Link><Link href="/assistant">What am I missing?</Link><Link href="/assistant">How should I apply?</Link><Link href="/assistant">Help me prepare</Link></div></section>
    </div><aside className="opportunity-detail-aside">
      {item.application_mode === "internal" ? <div className="opportunity-action-card"><span className="eyebrow">APPLY THROUGH GETNEBA</span><h2>Start a conversation</h2><p>Introduce yourself and choose the profile details you want the provider to see.</p>{tracked ? <span className="button button-dark full-width"><Check size={16} /> Application sent</span> : <button className="button button-dark full-width" onClick={startTracking} disabled={tracking}><HeartHandshake size={16} /> Apply internally</button>}{applyOpen && <div className="internal-apply-backdrop"><div className="internal-apply-modal" role="dialog" aria-modal="true" aria-labelledby="internal-apply-title"><div className="internal-apply-modal-header"><div><span className="eyebrow">APPLY INTERNALLY</span><h3 id="internal-apply-title">Start a conversation</h3><p>Send a short introduction and choose what the provider can review.</p></div><button type="button" className="internal-apply-close" onClick={() => setApplyOpen(false)} aria-label="Close application form"><X size={18} /></button></div><div className="internal-apply-form"><div className="internal-apply-intro"><span className="internal-apply-marker">1</span><div><strong>Introduce yourself</strong><small>A short, specific note makes it easier for the provider to respond.</small></div></div><label className="internal-apply-field"><span>Message <small>Required</small></span><textarea rows={5} value={applicationMessage} onChange={(event) => setApplicationMessage(event.target.value)} maxLength={2000} placeholder="Hi, I’m interested in this opportunity because…" /><small className="internal-apply-count">{applicationMessage.length}/2000</small></label><fieldset className="internal-apply-share"><legend><span className="internal-apply-marker">2</span><span><strong>Choose what to share</strong><small>Only the details you select will be sent to the provider.</small></span></legend><div className="internal-apply-share-grid">{shareOptions.map(([value, label, description]) => <label className={`internal-apply-share-option${sharedFields.includes(value) ? " selected" : ""}`} key={value}><input type="checkbox" checked={sharedFields.includes(value)} onChange={() => setSharedFields((current) => current.includes(value) ? current.filter((entry) => entry !== value) : [...current, value])} /><span className="internal-apply-check"><Check size={12} /></span><span><strong>{label}</strong><small>{description}</small></span></label>)}</div></fieldset><label className="internal-apply-field"><span>Anything else? <small>Optional</small></span><textarea rows={3} value={additionalInformation} onChange={(event) => setAdditionalInformation(event.target.value)} maxLength={3000} placeholder="Add context that could help your application." /></label><div className="internal-apply-footer"><small>Your application will be sent privately to the opportunity provider.</small><button className="button button-dark full-width" onClick={submitApplication} disabled={tracking}>{tracking ? "Sending application…" : "Send application"}</button></div></div></div></div>}</div> : <div className="opportunity-action-card"><span className="eyebrow">OFFICIAL APPLICATION</span><h2>Apply with {item.provider}</h2><p>GetNeba helps you prepare and track progress. Your application is submitted on the provider&apos;s website.</p><a className="button button-dark full-width" href={item.application_url} target="_blank" rel="noreferrer">Open provider website <ExternalLink size={15} /></a>{tracked ? <span className="opportunity-tracked"><Check size={14} /> Added to your private tracker</span> : <button className="button button-outline full-width" onClick={startExternalTracking} disabled={tracking}>{tracking ? "Adding…" : "Track my progress"}</button>}</div>}
      {remaining !== null && <div className="deadline-intelligence"><span className="eyebrow">YOUR DEADLINE</span><strong>{remaining} days remaining</strong><p>{remaining > 14 ? "You have enough time to prepare with intention." : "This deadline is getting close. Start with the most important step today."}</p><div className="deadline-schedule"><span><b>Today</b> Review your fit</span><span><b>This week</b> Prepare your application</span><span><b>Deadline</b> Submit on time</span></div></div>}
      <div className="opportunity-source-card"><span className="eyebrow">OFFERED BY</span><strong>{item.provider}</strong>{item.verification && <small>{item.verification.label}</small>}{item.source_url && <a href={item.source_url} target="_blank" rel="noreferrer">Original source <ExternalLink size={13} /></a>}<small>GetNeba helps you understand and prepare. The provider makes the final decision.</small></div>
      <OpportunityCommunityActions opportunity={item} authenticated={authenticated} loginHref={loginHref} />
    </aside></div>
    {similar.length > 0 && <section className="opportunity-similar"><div className="opportunity-section-heading compact"><div><span className="eyebrow">KEEP EXPLORING</span><h2>More opportunities for you</h2></div></div><div className="opportunity-similar-grid">{similar.map((candidate) => <Link href={opportunityPath(candidate.title, candidate.public_id)} key={candidate.public_id}>{candidate.match && <span>{candidate.match.score}% match</span>}<strong>{candidate.title}</strong><small>{candidate.provider}</small><ChevronRight size={16} /></Link>)}</div></section>}
  </main>;
}
